contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(true);

        // Account must start with zero stake on the fresh contract.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        // A zero-amount withdraw must always revert ("Cannot withdraw 0").
        bool revertedZero;
        try c.withdraw(0, false) { revertedZero = false; } catch { revertedZero = true; }

        // A positive-amount withdraw with no prior stake must revert
        // ("Not enough staked tokens") and must not change balances.
        bool reverted;
        if (amount > 0) {
            try c.withdraw(amount, false) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        assert(
            revertedZero &&
            reverted &&
            balBefore == 0 &&
            supplyBefore == 0 &&
            balAfter == balBefore &&
            supplyAfter == supplyBefore
        );
    }

    receive() external payable {}
}

