contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // Precondition-free: works for every amount on any state.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.withdraw(amount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        if (reverted) {
            // Reverting must leave balances untouched.
            assert(balAfter == balBefore && supplyAfter == supplyBefore);
        } else {
            // Success requires a positive amount within the staked balance,
            // and must reduce both the account balance and total supply by exactly amount.
            assert(amount > 0 && amount <= balBefore && balAfter == balBefore - amount && supplyAfter == supplyBefore - amount);
        }
    }

    receive() external payable {}
}

